<?php declare(strict_types=1);require_once __DIR__.'/includes/auth.php';$merchant=require_login();$pageTitle='Transactions';$status=$_GET['status']??'';$search=substr(trim((string)($_GET['search']??'')),0,80);$page=max(1,(int)($_GET['page']??1));$limit=20;$where='merchant_id=?';$params=[$merchant['id']];if(in_array($status,['pending','success','expired'],true)){$where.=' AND status=?';$params[]=$status;}if($search!==''){$where.=' AND (order_id LIKE ? OR utr LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';}$q=db()->prepare("SELECT order_id,customer_name,customer_email,amount,status,utr,created_at FROM orders WHERE $where ORDER BY created_at DESC LIMIT $limit OFFSET ".(($page-1)*$limit));$q->execute($params);$rows=$q->fetchAll();require __DIR__.'/includes/dashboard-header.php';?>
<div class="page-title"><div><h1>Transactions</h1><p>Review and search your payment orders.</p></div></div><div class="card"><form method="get" style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:17px"><input class="field" style="max-width:260px;border:1px solid var(--line);border-radius:8px;padding:9px 12px" name="search" value="<?=h($search)?>" placeholder="Order ID or UTR"><select name="status" style="border:1px solid var(--line);border-radius:8px;padding:9px"><option value="">All statuses</option><?php foreach(['pending'=>'Pending','success'=>'Successful','expired'=>'Expired'] as $k=>$v):?><option value="<?=$k?>" <?=$status===$k?'selected':''?>><?=$v?></option><?php endforeach?></select><button class="btn" style="padding:9px 15px">Filter</button></form><div class="table-wrap"><table><thead><tr><th>ORDER ID</th><th>CUSTOMER</th><th>AMOUNT</th><th>UTR</th><th>STATUS</th><th>CREATED</th><th>ACTION</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" style="text-align:center;padding:28px;color:#8390a3">No matching transactions found.</td></tr><?php endif?><?php foreach($rows as $r):?><tr><td><strong><?=h($r['order_id'])?></strong></td><td><?=h($r['customer_name']?:$r['customer_email']?:'—')?></td><td>₹<?=number_format((float)$r['amount'],2)?></td><td><?=h($r['utr']?:'—')?></td><td><span class="badge badge-<?=h($r['status'])?>"><?=h(ucfirst($r['status']))?></span></td><td><?=h(date('M j, Y',strtotime($r['created_at'])))?></td><td><?php if($r['status']==='success'):?><a href="/invoice.php?order_id=<?=rawurlencode($r['order_id'])?>" style="color:var(--blue)">Invoice ↗</a><?php else:?>—<?php endif?></td></tr><?php endforeach?></tbody></table></div><div style="display:flex;justify-content:space-between;margin-top:17px;font-size:10px;color:#718097"><span>Page <?=$page?></span><span><a href="?<?=http_build_query(['status'=>$status,'search'=>$search,'page'=>max(1,$page-1)])?>">← Previous</a>　 <a href="?<?=http_build_query(['status'=>$status,'search'=>$search,'page'=>$page+1])?>">Next →</a></span></div></div><?php require __DIR__.'/includes/dashboard-footer.php';?>